import 'dart:convert';import 'package:http/http.dart' as http;import 'package:supabase_flutter/supabase_flutter.dart';import 'voice_receptionist_models.dart';class VoiceReceptionistRepository{VoiceReceptionistRepository(this.baseUrl,this.client);final String baseUrl;final SupabaseClient client;Future<Map<String,String>> _h()async{final t=client.auth.currentSession?.accessToken;if(t==null)throw Exception('Sign in required.');return {'Authorization':'Bearer $t','Content-Type':'application/json'};}Future<dynamic> _c(String p,{String m='GET',Map<String,dynamic>? b})async{final u=Uri.parse('$baseUrl$p'),h=await _h();final r=m=='POST'?await http.post(u,headers:h,body:jsonEncode(b??{})):m=='PATCH'?await http.patch(u,headers:h,body:jsonEncode(b??{})):await http.get(u,headers:h);if(r.statusCode>=400)throw Exception('Voice request failed.');return jsonDecode(r.body);}Future<VoiceAgentState> state()async=>VoiceAgentState.fromJson(Map<String,dynamic>.from(await _c('/api/v1/agents/voice')));Future<void> status(String s)async{await _c('/api/v1/agents/voice/status',m:'POST',b:{'status':s});}Future<VoicePolicy> policy()async=>VoicePolicy.fromJson(Map<String,dynamic>.from((await _c('/api/v1/agents/voice/policy'))['policy']??{}));Future<void> save(VoicePolicy p)async{await _c('/api/v1/agents/voice/policy',m:'PATCH',b:p.toJson());}Future<VoiceRunResult> run(String number,String name,String transcript)async=>VoiceRunResult.fromJson(Map<String,dynamic>.from(await _c('/api/v1/agents/voice/run',m:'POST',b:{'callerNumber':number,'callerName':name,'transcript':transcript})));}
